def test_product_even(limit=100):
    for n in range(-limit, limit+1):
        prod = n * (n+1)
        if prod % 2 != 0:
            return False, n, prod
    return True, None, None

passed, counter_n, counter_prod = test_product_even(100)
print(f"所有整数 n 在 [-100, 100] 范围内 n(n+1) 都是偶数: {passed}")
if not passed:
    print(f"反例: n={counter_n}, n(n+1)={counter_prod}")

def test_product_even(limit=1000):
    for n in range(-limit, limit+1):
        if (n * (n+1)) % 2 != 0:
            return False, n, n*(n+1)
    return True, None, None

passed, counter_n, counter_prod = test_product_even(1000)
print(f"测试范围 n ∈ [-1000, 1000]")
print(f"所有 n(n+1) 均为偶数: {passed}")
if not passed:
    print(f"反例: n={counter_n}, n(n+1)={counter_prod}")
